// frontend/src/services/api.js
import axios from 'axios';

const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:5000';

// Instance chung cho tất cả API
const commonAPI = axios.create({
  baseURL: `${API_BASE}/api`,
  headers: {
    'Content-Type': 'application/json',
  },
});

/**
 * Tin tức
 */
export const fetchNews = async (params = {}) => {
  try {
    const { page = 1, limit = 12 } = params;
    const response = await commonAPI.get('/news', { params: { page, limit } });
    return response.data;
  } catch (error) {
    console.error('Lỗi khi tải tin tức:', error);
    return { articles: [], total: 0, page: 1, limit };
  }
};

export const fetchArticle = async (id) => {
  try {
    const response = await commonAPI.get(`/news/${id}`);
    return response.data.article;
  } catch (error) {
    console.error('Lỗi khi tải bài viết:', error);
    if (error.response?.status === 404) {
      throw new Error('Bài viết không tồn tại');
    }
    throw error;
  }
};

/**
 * Marketplace / Landing Page
 */

// Clone landing page vào kho cá nhân
export const cloneLanding = async ({ userId, templateId, name }) => {
  try {
    const res = await commonAPI.post('/landing/clone', { userId, templateId, name });
    return res.data; // { landingPage: {...} }
  } catch (error) {
    console.error('Lỗi clone landing:', error);
    throw error;
  }
};

// Lấy danh sách landing page của user
export const getMyLandingPages = async (userId) => {
  try {
    const res = await commonAPI.get(`/landing/my/${userId}`);
    return res.data; // [{ _id, name, templateId, landingPageUrl, ... }]
  } catch (error) {
    console.error('Lỗi lấy kho landing:', error);
    return [];
  }
};

// Giữ nguyên leadsAPI nếu được dùng ở nơi khác
export const leadsAPI = axios.create({
  baseURL: `${API_BASE}/api`,
});

export default commonAPI;
